const AVISO_IDIOMA = {
  en: "ℹ️ The interface, glossary, item summaries, in-depth sections, lessons, quiz and claims are translated. Some long or dynamic texts (e.g. live data, news) may still appear in Portuguese.",
  es: "ℹ️ La interfaz, el glosario, los resúmenes, las secciones detalladas, las lecciones, el quiz y las afirmaciones están traducidos. Algunos textos largos o dinámicos (p. ej. datos en vivo, noticias) pueden seguir en portugués."
};

/* i18n-conteudo.js só é baixado quando o idioma não é português; ele enfileira o código aqui. */
(window.__I18N_Q || []).forEach(f => f());
window.__I18N_Q = { push: f => f() };

function tr(txt) {
  if (LANG === "pt") return txt;
  const k0 = txt.trim();
  if (!k0) return txt;
  const k = k0.replace(/\s+/g, " ");
  const dic = I18N[LANG];
  let r = dic[k];
  if (r === undefined) {
    for (const [re, sub] of I18N_REGEX[LANG]) {
      if (re.test(k)) { r = k.replace(re, sub); break; }
    }
  }
  if (r === undefined) {
    // prefixo de emoji/símbolo seguido do texto (ex.: "✅ Correto!" já tratado; "🔵 Em estudo clínico")
    const m = k.match(/^(\S+)\s+(.+)$/);
    if (m && !/[\p{L}\d]/u.test(m[1]) && dic[m[2]] !== undefined) r = m[1] + " " + dic[m[2]];
  }
  return r === undefined ? txt : txt.replace(k0, () => r);
}

const ATRIBUTOS = ["placeholder", "aria-label", "title"];
function traduzirNo(no) {
  if (no.nodeType === 3) {
    const novo = tr(no.nodeValue);
    if (novo !== no.nodeValue) no.nodeValue = novo;
    return;
  }
  if (no.nodeType !== 1 || ["SCRIPT", "STYLE", "SELECT#idioma"].includes(no.tagName)) return;
  if (no.id === "idioma") return;
  ATRIBUTOS.forEach(a => {
    if (no.hasAttribute(a)) { const v = no.getAttribute(a), n = tr(v); if (n !== v) no.setAttribute(a, n); }
  });
  no.childNodes.forEach(traduzirNo);
}

function iniciarI18n() {
  if (LANG === "pt" || window.__i18n) return;
  window.__i18n = true;
  document.documentElement.lang = LANG;
  const topo = document.getElementById("topo");
  if (topo && !topo.querySelector(".aviso-idioma")) {
    const p = document.createElement("p");
    p.className = "aviso-idioma";
    p.textContent = AVISO_IDIOMA[LANG];
    topo.appendChild(p);
  }
  traduzirNo(document.body);
  document.title = tr(document.title);
  let agendado = false;
  window.__i18nObserver = new MutationObserver(muts => {
    if (agendado) return;
    agendado = true;
    requestAnimationFrame(() => { agendado = false; traduzirNo(document.body); });
  });
  window.__i18nObserver.observe(document.body, { childList: true, subtree: true, characterData: true, attributes: true, attributeFilter: ATRIBUTOS });
}
